SELECT ?year (AVG(?annualPrecipitation) AS ?averageAnnualPrecipitation)
WHERE {
  {
    SELECT ?catchment (YEAR(?time) AS ?year) (SUM(xsd:decimal(?precipValue)) AS ?annualPrecipitation)
